# Another hypothesis: Only fill rows 2, 4, 7, 10 (the ones with 8s), keep row 0 as is
def fill_gaps_only_8_rows(grid):
    result = [row[:] for row in grid]  # copy
    for r in range(len(result)):
        # Find rows that had any 8s, and fill their gaps
        if any(c == 8 for c in grid[r]):
            for c in range(len(result[r])):
                if result[r][c] == 0:
                    result[r][c] = 8
    return result

