for row in fill_gaps_only_8_rows(grid):
    print(' '.join(map(str, row)))

# Final hypothesis test: Fill only the rows that contain 8s
# Keep row 0 unchanged, make each row with 8s into solid lines

def solve(grid):
    result = [row[:] for row in grid]
    for r in range(len(result)):
        # If this row has any 8s, fill its gaps
        if 8 in grid[r]:
            for c in range(len(result[r])):
                if result[r][c] == 0:
                    result[r][c] = 8
    return result

